-- Indexed notification pages and bounded exceptional-record probes.
CREATE INDEX IF NOT EXISTS idx_cf_notif_page ON friendbook_cf_firestore_documents (json_extract(document_json,'$.toUserId'), (CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN 2 ELSE 4 END), (CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN json_extract(document_json,'$.createdAt') ELSE json_extract(document_json,'$.createdAt.millis') END), doc_id) WHERE parent_path='notifications';
CREATE INDEX IF NOT EXISTS idx_cf_notif_unread ON friendbook_cf_firestore_documents (json_extract(document_json,'$.toUserId'), (CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN 2 ELSE 4 END), (CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN json_extract(document_json,'$.createdAt') ELSE json_extract(document_json,'$.createdAt.millis') END), doc_id) WHERE parent_path='notifications' AND json_type(document_json,'$.isRead')='false';
CREATE INDEX IF NOT EXISTS idx_cf_notif_exceptions ON friendbook_cf_firestore_documents (json_extract(document_json,'$.toUserId'),doc_id) WHERE parent_path='notifications' AND (doc_id GLOB '*[^ -~]*' OR path<>'notifications/'||doc_id OR COALESCE(((json_type(document_json,'$.createdAt') IN ('integer','real') AND json_extract(document_json,'$.createdAt') BETWEEN -9007199254740991 AND 9007199254740991)
    OR (json_type(document_json,'$.createdAt')='object' AND json_extract(document_json,'$.createdAt.__type')='timestamp'
      AND json_type(document_json,'$.createdAt.millis')='integer' AND json_extract(document_json,'$.createdAt.millis') BETWEEN -9007199254740991 AND 9007199254740991)),0)=0);
CREATE INDEX IF NOT EXISTS idx_cf_legacy_notif_page ON friendbook_cf_documents ((CASE WHEN json_type(document_json,'$.fields')='object' THEN json_extract(document_json,'$.fields.toUserId.stringValue') ELSE json_extract(document_json,'$.toUserId') END), (CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN 2 ELSE 4 END), (CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN json_extract(document_json,'$.createdAt') ELSE json_extract(document_json,'$.createdAt.millis') END), doc_id) WHERE collection='notifications';
CREATE INDEX IF NOT EXISTS idx_cf_legacy_notif_unread ON friendbook_cf_documents ((CASE WHEN json_type(document_json,'$.fields')='object' THEN json_extract(document_json,'$.fields.toUserId.stringValue') ELSE json_extract(document_json,'$.toUserId') END), (CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN 2 ELSE 4 END), (CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN json_extract(document_json,'$.createdAt') ELSE json_extract(document_json,'$.createdAt.millis') END), doc_id) WHERE collection='notifications' AND json_type(document_json,'$.isRead')='false';
CREATE INDEX IF NOT EXISTS idx_cf_legacy_notif_exceptions ON friendbook_cf_documents ((CASE WHEN json_type(document_json,'$.fields')='object' THEN json_extract(document_json,'$.fields.toUserId.stringValue') ELSE json_extract(document_json,'$.toUserId') END),doc_id) WHERE collection='notifications' AND (doc_id GLOB '*[^ -~]*' OR path<>'notifications/'||doc_id OR json_type(document_json,'$.fields')='object' OR COALESCE(((json_type(document_json,'$.createdAt') IN ('integer','real') AND json_extract(document_json,'$.createdAt') BETWEEN -9007199254740991 AND 9007199254740991)
    OR (json_type(document_json,'$.createdAt')='object' AND json_extract(document_json,'$.createdAt.__type')='timestamp'
      AND json_type(document_json,'$.createdAt.millis')='integer' AND json_extract(document_json,'$.createdAt.millis') BETWEEN -9007199254740991 AND 9007199254740991)),0)=0);
